using System.Reflection;
using System.Text.Json.Serialization;
using Maxx.Api.Autenticacao;
using Maxx.Api.Demonstracao;
using Maxx.Api.Erros;
using Maxx.Api.Feed;
using Maxx.Api.Fotos;
using Maxx.Api.Health;
using Maxx.Api.Instituicao;
using Maxx.Api.LimiteDeTaxa;
using Maxx.Api.Medalhas;
using Maxx.Api.Mural;
using Maxx.Api.Notificacoes;
using Maxx.Api.OpenApi;
using Maxx.Api.Perfil;
using Maxx.Api.Posts;
using Maxx.Api.Premios;
using Maxx.Api.PremiosParticipacao;
using Maxx.Api.Ranking;
using Maxx.Api.Social;
using Maxx.Infrastructure;
using Maxx.Infrastructure.Fila;
using Maxx.Infrastructure.Persistence;
using Maxx.Infrastructure.Seed;

// `Maxx.Api migrate` roda as migrations e sai. É o comando do contêiner de migração.
var isMigrate = args is ["migrate", ..];

// `Maxx.Api seed <base|demo>` grava os dados de data/ e sai. Idempotente.
var isSeed = args is ["seed", ..];

// `Maxx.Api anular-medalha <id> --instituicao <e-mail>` anula uma medalha e sai: a anulação
// da fase 1, por comando administrativo (ComandoDeAnulacao).
var isAnulacao = args is [ComandoDeAnulacao.Nome, ..];

// `Maxx.Api worker` consome a fila de trabalhos do Postgres (ADR 0008), sem servidor HTTP.
// É o comando do contêiner do worker; as réplicas da API só enfileiram.
if (args is ["worker", ..])
{
    var worker = Host.CreateApplicationBuilder(args[1..]);
    worker.Services.AddSingleton(TimeProvider.System);
    worker.Services.AddInfrastructure(
        worker.Configuration.GetConnectionString("Maxx")
            ?? throw new InvalidOperationException("ConnectionStrings:Maxx não configurada."));
    worker.AddEnvioDeEmail(exigirUrl: true);
    worker.AddArmazenamentoDeFotos(exigir: true);
    worker.Services.AddWorker();
    await worker.Build().RunAsync();
    return 0;
}

// A geração do OpenAPI no build sobe a aplicação sem servidor e sem banco.
var isOpenApiGeneration = Assembly.GetEntryAssembly()?.GetName().Name == "GetDocument.Insider";

var builder = WebApplication.CreateBuilder(
    isMigrate ? args[1..]
    : isSeed ? args[Math.Min(2, args.Length)..]
    : isAnulacao ? args[Math.Min(ComandoDeAnulacao.Argumentos, args.Length)..]
    : args);

var connectionString = builder.Configuration.GetConnectionString("Maxx")
    ?? (isOpenApiGeneration ? "Host=openapi-generation" : null)
    ?? throw new InvalidOperationException("ConnectionStrings:Maxx não configurada.");

builder.Services.AddProblemDetails(Erro.Customizar);

// Número só como número: o padrão web aceita "42" em texto, e o contrato viraria
// `number | string` em todo campo numérico do cliente TypeScript.
builder.Services.ConfigureHttpJsonOptions(options =>
    options.SerializerOptions.NumberHandling = JsonNumberHandling.Strict);

builder.Services.AddOpenApi(options => options
    .AddDocumentTransformer((document, _, _) =>
    {
        document.Info.Title = "Maxx API";
        document.Info.Version = "v1";
        return Task.CompletedTask;
    })
    .AddBearerSecurity());
builder.Services.AddInfrastructure(connectionString);
builder.Services.Configure<SeedOptions>(builder.Configuration.GetSection(SeedOptions.Section));

builder.Services.AddSingleton(TimeProvider.System);

// Validação de entrada na borda; a recusa sai em ProblemDetails como o resto.
builder.Services.AddValidation();
builder.Services.AddExceptionHandler<RecusaExceptionHandler>();
builder.Services.AddExceptionHandler<DomainExceptionHandler>();

var servindo = !isMigrate && !isSeed && !isAnulacao && !isOpenApiGeneration;
builder.AddAutenticacao(exigirChave: servindo);
builder.AddArmazenamentoDeFotos(exigir: servindo);
var demonstracao = builder.AddDemonstracao(servindo: servindo, gerandoOpenApi: isOpenApiGeneration);
builder.Services.AddProxyConfiavel(builder.Configuration);
builder.Services.AddLimitesDeTaxa();
builder.Services.AddScoped<Maxx.Application.Medalhas.ConcederMedalhaHandler>();
builder.Services.AddScoped<Maxx.Application.Medalhas.AnularMedalhaHandler>();
builder.Services.AddScoped<Maxx.Application.Fotos.PedirUploadHandler>();
builder.Services.AddScoped<Maxx.Application.Posts.PublicarPostHandler>();
builder.Services.AddScoped<Maxx.Application.Posts.RemoverPostHandler>();
builder.Services.AddScoped<Maxx.Application.Social.CurtidaHandler>();
builder.Services.AddScoped<Maxx.Application.Social.ComentarioHandler>();
builder.Services.AddScoped<Maxx.Application.Social.SeguimentoHandler>();
builder.Services.AddScoped<Maxx.Application.Feed.FeedHandler>();
builder.Services.AddScoped<Maxx.Application.Perfil.EditarPerfilHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.EventosHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.MateriasDoAlunoHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.ReivindicarHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.DecidirComprovacaoHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.FilaDeComprovacoesHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.ContestacaoHandler>();
builder.Services.AddScoped<Maxx.Application.Perfil.BuscaDeAlunosHandler>();
builder.Services.AddScoped<Maxx.Application.Ranking.LeituraDoRankingHandler>();
builder.Services.AddScoped<Maxx.Application.Mural.PublicarAvisoHandler>();
builder.Services.AddScoped<Maxx.Application.Mural.MuralHandler>();
builder.Services.AddScoped<Maxx.Application.Notificacoes.NotificacoesHandler>();
builder.Services.AddScoped<Maxx.Application.Instituicao.AtosSobreOAlunoHandler>();
builder.Services.AddScoped<Maxx.Application.Instituicao.ConcessaoDiretaHandler>();
builder.Services.AddScoped<Maxx.Application.Instituicao.PurgaDaDemonstracaoHandler>();

var app = builder.Build();

if (isMigrate)
{
    await using var scope = app.Services.CreateAsyncScope();
    await scope.ServiceProvider.GetRequiredService<DatabaseMigrator>().MigrateAsync(CancellationToken.None);
    return 0;
}

if (isSeed)
{
    if (args is not [_, var nomeDoPerfil, ..] || !Enum.TryParse<PerfilDeSeed>(nomeDoPerfil, ignoreCase: true, out var perfil)
        || !Enum.IsDefined(perfil))
    {
        await Console.Error.WriteLineAsync("Uso: Maxx.Api seed <base|demo>");
        return 2;
    }

    await using var scope = app.Services.CreateAsyncScope();
    try
    {
        await scope.ServiceProvider.GetRequiredService<DatabaseSeeder>().SeedAsync(perfil, CancellationToken.None);
    }
    catch (SeedException ex)
    {
        // Dado recusado é resposta esperada, não falha do programa: sem pilha no log.
        await Console.Error.WriteLineAsync(ex.Message);
        return 1;
    }

    return 0;
}

if (isAnulacao)
{
    await using var scope = app.Services.CreateAsyncScope();
    return await ComandoDeAnulacao.ExecutarAsync(scope.ServiceProvider, args, Console.Out, Console.Error, CancellationToken.None);
}

// Primeiro de tudo: o IP e o esquema reais vêm do Caddy, e só dele.
app.UseForwardedHeaders();

// Um formato só de erro: ProblemDetails (RFC 9457).
app.UseExceptionHandler();
app.UseStatusCodePages();

app.UseAuthentication();
app.UseAuthorization();

// Origem única (ADR 0001): toda rota da API vive sob /api, e o Caddy não corta o prefixo.
var api = app.MapGroup("/api");
api.MapHealthEndpoints();

// Contrato versionado: só mudanças aditivas. Fechado por padrão: toda rota de /v1 exige
// login, e a pública diz isso com AllowAnonymous. No grupo, e não numa FallbackPolicy,
// porque a fallback vale também para pedido sem endpoint, e rota inexistente tem de
// continuar 404 (as rotas da demonstração desligada respondem igual a ela).
var v1 = api.MapGroup("/v1").RequireAuthorization();
v1.MapEuEndpoints();
v1.MapTermoDeUsoEndpoints();
v1.MapProfessorEndpoints();
v1.MapPremiosEndpoints();
v1.MapUploadEndpoints();
v1.MapPostEndpoints();
v1.MapSocialEndpoints();
v1.MapFeedEndpoints();
v1.MapPerfilEndpoints();
v1.MapEventoEndpoints();
v1.MapComprovacaoEndpoints();
v1.MapContestacaoEndpoints();
v1.MapAvisoEndpoints();
v1.MapNotificacaoEndpoints();
v1.MapRankingEndpoints();
v1.MapInstituicaoEndpoints();
v1.MapGroup("/auth").AllowAnonymous().MapCadastroEndpoints().MapLoginEndpoints().MapRecuperacaoEndpoints();
if (demonstracao)
{
    v1.MapDemonstracaoEndpoints();
}

if (app.Environment.IsDevelopment())
{
    api.MapOpenApi("/openapi/{documentName}.json");
}

await app.RunAsync();
return 0;

