1	using System.Security.Cryptography;
2	using Maxx.Application.Autenticacao;
3	using Maxx.Application.Autenticacao.Cadastro;
4	using Maxx.Application.Autenticacao.Login;
5	using Maxx.Application.Autenticacao.Recuperacao;
6	using Maxx.Application.Autenticacao.Termos;
7	using Maxx.Infrastructure.Email;
8	using Microsoft.AspNetCore.Authentication.JwtBearer;
9	using Microsoft.IdentityModel.Tokens;
10	
11	namespace Maxx.Api.Autenticacao;
12	
13	internal static class AutenticacaoServiceCollectionExtensions
14	{
15	    // exigirChave é falso só nos subcomandos (migrate, seed) e na geração do OpenAPI, que
16	    // não servem requisição. Fora de desenvolvimento, sem chave válida a API não sobe.
17	    public static WebApplicationBuilder AddAutenticacao(this WebApplicationBuilder builder, bool exigirChave)
18	    {
19	        var chave = LerChave(builder, exigirChave);
20	        builder.Services.AddSingleton(new ChaveDeAssinatura(chave));
21	        builder.Services.AddSingleton<IAccessTokenIssuer, JwtAccessTokenIssuer>();
22	        builder.Services.AddScoped<SessaoService>();
23	        builder.Services.AddScoped<SugestaoDeArroba>();
24	        builder.Services.AddScoped<TermoDeUsoHandler>();
25	        builder.Services.AddScoped<CadastroHandler>();
26	        builder.Services.AddScoped<LoginHandler>();
27	        builder.Services.AddScoped<RefreshHandler>();
28	        builder.Services.AddScoped<LogoutHandler>();
29	        builder.Services.AddScoped<RecuperacaoHandler>();
30	        builder.AddEnvioDeEmail(exigirChave);
31	
32	        builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
33	            .AddJwtBearer(options =>
34	            {
35	                // Claims com o nome que vieram (sub, papel), sem o mapeamento para os URIs
36	                // do WS-Federation.
37	                options.MapInboundClaims = false;
38	                options.TokenValidationParameters = new TokenValidationParameters
39	                {
40	                    ValidIssuer = JwtOptions.Emissor,
41	                    ValidAudience = JwtOptions.Audiencia,
42	                    IssuerSigningKey = chave,
43	                    ValidAlgorithms = [SecurityAlgorithms.HmacSha256],
44	                    ClockSkew = JwtOptions.Tolerancia,
45	                    NameClaimType = MaxxClaims.Sub,
46	                    RoleClaimType = MaxxClaims.Papel,
47	                };
48	            });
49	        builder.Services.AddAuthorization(Politicas.Configurar);
50	
51	        return builder;
52	    }
53	
54	    // O que o handler do e-mail de recuperação precisa da borda: SMTP e URL pública do app.
55	    // Na API e no worker: quem executa o trabalho é o worker, e a API e os testes de
56	    // integração montam os mesmos tipos de trabalho.
57	    public static IHostApplicationBuilder AddEnvioDeEmail(this IHostApplicationBuilder builder, bool exigirUrl)
58	    {
59	        builder.Services.AddSingleton<ILinkDoApp>(new LinkDoApp(LerUrlPublica(builder, exigirUrl)));
60	        builder.Services.Configure<EmailOptions>(builder.Configuration.GetSection(EmailOptions.Section));
61	        return builder;
62	    }
63	
64	    // Sem ela o link do e-mail de recuperação não teria para onde apontar: fora de
65	    // desenvolvimento nem a API nem o worker sobem.
66	    private static Uri LerUrlPublica(IHostApplicationBuilder builder, bool exigir)
67	    {
68	        var texto = builder.Configuration[$"{LinkDoApp.Section}:UrlPublica"];
69	        if (string.IsNullOrWhiteSpace(texto))
70	        {
71	            if (exigir && !builder.Environment.IsDevelopment())
72	            {
73	                throw new InvalidOperationException($"{LinkDoApp.Section}__UrlPublica não configurada: defina a URL pública do app.");
74	            }
75	
76	            texto = "http://localhost";
77	        }
78	
79	        if (!Uri.TryCreate(texto.Trim().TrimEnd('/') + "/", UriKind.Absolute, out var url) || url.Scheme is not ("http" or "https"))
80	        {
81	            throw new InvalidOperationException($"{LinkDoApp.Section}__UrlPublica inválida: {texto}.");
82	        }
83	
84	        return url;
85	    }
86	
87	    private static SymmetricSecurityKey LerChave(WebApplicationBuilder builder, bool exigirChave)
88	    {
89	        var texto = builder.Configuration.GetSection(JwtOptions.Section).Get<JwtOptions>()?.Chave;
90	
91	        if (string.IsNullOrWhiteSpace(texto))
92	        {
93	            if (exigirChave && !builder.Environment.IsDevelopment())
94	            {
95	                throw new InvalidOperationException(
96	                    $"{JwtOptions.Section}__Chave não configurada: defina uma chave base64 de ao menos {JwtOptions.TamanhoMinimoDaChaveEmBytes} bytes.");
97	            }
98	
99	            // Desenvolvimento sem chave: uma por processo, que some no restart. Nada
100	            // versionado, nem a chave de desenvolvimento.
101	            return new SymmetricSecurityKey(RandomNumberGenerator.GetBytes(JwtOptions.TamanhoMinimoDaChaveEmBytes));
102	        }
103	
104	        var bytes = new byte[texto.Length];
105	        if (!Convert.TryFromBase64String(texto.Trim(), bytes, out var escritos) || escritos < JwtOptions.TamanhoMinimoDaChaveEmBytes)
106	        {
107	            throw new InvalidOperationException(
108	                $"{JwtOptions.Section}__Chave inválida: tem de ser base64 de ao menos {JwtOptions.TamanhoMinimoDaChaveEmBytes} bytes.");
109	        }
110	
111	        return new SymmetricSecurityKey(bytes[..escritos]);
112	    }
113	}
