1	namespace Maxx.Application.Autenticacao.Login;
2	
3	// O login (fluxos/01-login.md): aluno por RA ou por e-mail, professor e instituição só
4	// por e-mail. Toda falha tem a mesma resposta e o mesmo custo de um Argon2id, para que
5	// nem o corpo nem o tempo digam se a conta existe (ADR 0006).
6	public sealed class LoginHandler(IUsuarioRepository usuarios, ISenhaHasher senhas, SessaoService sessoes, IUnitOfWork unitOfWork)
7	{
8	    public async Task<Sessao> EntrarAsync(Credenciais credenciais, CancellationToken cancellationToken)
9	    {
10	        ArgumentNullException.ThrowIfNull(credenciais);
11	
12	        // Com arroba é e-mail; sem, é RA. E-mail não tem forma de RA, nem RA de e-mail.
13	        var identificador = credenciais.Identificador.Trim();
14	        var usuario = identificador.Contains('@', StringComparison.Ordinal)
15	            ? await usuarios.BuscarPorEmailAsync(identificador, cancellationToken)
16	            : await usuarios.BuscarAlunoPorRaAsync(identificador, cancellationToken);
17	
18	        // Conta do seed que ainda não definiu senha entra pela recuperação, não por aqui.
19	        if (usuario?.HashDaSenha is not { } hash)
20	        {
21	            senhas.VerifyDummy(credenciais.Senha);
22	            throw CredenciaisInvalidas("conta inexistente ou sem senha");
23	        }
24	
25	        if (!senhas.Verify(credenciais.Senha, hash))
26	        {
27	            throw CredenciaisInvalidas($"senha errada para o usuário {usuario.Id}");
28	        }
29	
30	        var sessao = sessoes.Abrir(usuario);
31	        await unitOfWork.SalvarAsync(cancellationToken);
32	        return sessao;
33	    }
34	
35	    // O motivo vai só para o log; o identificador digitado não vai nem para lá.
36	    private static RecusaException CredenciaisInvalidas(string motivo) =>
37	        new(TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.CredenciaisInvalidas, $"Login recusado: {motivo}.");
38	}
39	
40	// A senha em claro existe só neste pedido, a caminho do Verify.
41	public sealed record Credenciais(string Identificador, string Senha)
42	{
43	    // Nunca imprimir a senha, nem por acidente num log de objeto.
44	    public override string ToString() => "Credenciais { }";
45	}
