1	using Maxx.Application.Fila;
2	using Maxx.Domain;
3	using Maxx.Domain.Identidade;
4	
5	namespace Maxx.Application.Autenticacao.Recuperacao;
6	
7	// Recuperação de senha e primeiro acesso de quem vem do seed
8	// (fluxos/06-recuperacao-de-senha.md).
9	public sealed class RecuperacaoHandler(
10	    IUsuarioRepository usuarios,
11	    IRecuperacaoDeSenhaRepository recuperacoes,
12	    IFamiliaDeSessaoRepository familias,
13	    ITokenGenerator tokens,
14	    ISenhaHasher senhas,
15	    IFilaDeTrabalhos fila,
16	    IUnitOfWork unitOfWork,
17	    TimeProvider relogio)
18	{
19	    // Quem chama responde o mesmo exista o e-mail ou não: nada aqui volta para o cliente.
20	    public async Task SolicitarAsync(string email, CancellationToken cancellationToken)
21	    {
22	        ArgumentNullException.ThrowIfNull(email);
23	
24	        // Aluno que está na base mas ainda não criou conta não recebe nada: o caminho dele é
25	        // o cadastro. Aluno de demonstração também não: não tem senha, e o e-mail dele é de
26	        // um domínio que não existe.
27	        var usuario = await usuarios.BuscarPorEmailAsync(email.Trim(), cancellationToken);
28	        if (usuario is null || usuario.EhDemonstracao)
29	        {
30	            return;
31	        }
32	
33	        // O pedido e o trabalho do e-mail gravam juntos. O token só nasce no worker, na hora
34	        // do envio: a fila leva o id do pedido, nunca um segredo.
35	        var recuperacao = RecuperacaoDeSenha.Solicitar(usuario.Id, relogio.GetUtcNow());
36	        recuperacoes.Adicionar(recuperacao);
37	        fila.Enfileirar(new EmailDeRecuperacao(recuperacao.Id));
38	        await unitOfWork.SalvarAsync(cancellationToken);
39	    }
40	
41	    public async Task ConfirmarAsync(NovaSenha pedido, CancellationToken cancellationToken)
42	    {
43	        ArgumentNullException.ThrowIfNull(pedido);
44	
45	        try
46	        {
47	            PoliticaDeSenha.Validar(pedido.Senha);
48	        }
49	        catch (DomainException excecao)
50	        {
51	            throw new RecusaException(TipoDeRecusa.Invalido, CodigosDeRecusa.SenhaForaDaPolitica, excecao.Message);
52	        }
53	
54	        // Argon2id só para token que existe, e uma vez só, mesmo que a gravação se repita.
55	        var hashDaSenha = new Lazy<string>(() => senhas.Hash(pedido.Senha));
56	        try
57	        {
58	            await ConcluirAsync(pedido.Token, hashDaSenha, cancellationToken);
59	        }
60	        catch (ConflitoDeConcorrenciaException)
61	        {
62	            // Outro pedido usou o mesmo link entre a leitura e a gravação. Relido, ele já
63	            // aparece usado: a resposta é a de um link usado duas vezes em sequência.
64	            unitOfWork.Descartar();
65	            await ConcluirAsync(pedido.Token, hashDaSenha, cancellationToken);
66	        }
67	    }
68	
69	    private async Task ConcluirAsync(string token, Lazy<string> hashDaSenha, CancellationToken cancellationToken)
70	    {
71	        var recuperacao = await recuperacoes.BuscarPorHashAsync(tokens.Hash(token.Trim()), cancellationToken)
72	            ?? throw Invalida("token desconhecido");
73	        var usuario = await usuarios.BuscarAsync(recuperacao.UsuarioId, cancellationToken)
74	            ?? throw new InvalidOperationException($"A recuperação {recuperacao.Id} cita um usuário que não existe.");
75	
76	        var resultado = recuperacao.Concluir(
77	            usuario,
78	            hashDaSenha.Value,
79	            await familias.AtivasDoUsuarioAsync(usuario.Id, cancellationToken),
80	            await recuperacoes.PendentesDoUsuarioAsync(usuario.Id, cancellationToken),
81	            relogio.GetUtcNow());
82	
83	        if (resultado != ResultadoDaRecuperacao.Concluida)
84	        {
85	            throw Invalida($"pedido {recuperacao.Id}: {resultado}");
86	        }
87	
88	        await unitOfWork.SalvarAsync(cancellationToken);
89	    }
90	
91	    private static RecusaException Invalida(string motivo) =>
92	        new(TipoDeRecusa.Invalido, CodigosDeRecusa.RecuperacaoInvalida, $"Recuperação recusada: {motivo}.");
93	}
94	
95	// O trabalho de mandar o link de um pedido de recuperação.
96	public sealed record EmailDeRecuperacao(Guid RecuperacaoId) : ICargaDeTrabalho
97	{
98	    public static string Tipo => "email-de-recuperacao";
99	}
100	
101	// No worker: emite o token do pedido, grava o hash e manda o e-mail, na transação do
102	// trabalho. Falha no envio desfaz o hash e volta com recuo; a retentativa emite outro token.
103	// Se o envio sai e a transação não fecha, o link que chegou não vale: o usuário pede outro.
104	public sealed class EmailDeRecuperacaoHandler(
105	    IUsuarioRepository usuarios,
106	    ICadastroElegivelRepository cadastros,
107	    IRecuperacaoDeSenhaRepository recuperacoes,
108	    ITokenGenerator tokens,
109	    ILinkDoApp links,
110	    IEmailSender emails,
111	    IUnitOfWork unitOfWork,
112	    TimeProvider relogio) : ITrabalhoHandler<EmailDeRecuperacao>
113	{
114	    public async Task ExecutarAsync(EmailDeRecuperacao carga, CancellationToken cancellationToken)
115	    {
116	        ArgumentNullException.ThrowIfNull(carga);
117	
118	        // Pedido encerrado antes do envio (outro link já trocou a senha) ou apagado com o
119	        // usuário: não há o que mandar.
120	        var recuperacao = await recuperacoes.BuscarAsync(carga.RecuperacaoId, cancellationToken);
121	        if (recuperacao is null || !recuperacao.EstaAberta)
122	        {
123	            return;
124	        }
125	
126	        var usuario = await usuarios.BuscarAsync(recuperacao.UsuarioId, cancellationToken)
127	            ?? throw new InvalidOperationException($"A recuperação {recuperacao.Id} cita um usuário que não existe.");
128	        var para = await cadastros.EmailAsync(usuario.CadastroElegivelId, cancellationToken);
129	
130	        var token = tokens.Generate();
131	        recuperacao.EmitirToken(token.Hash, relogio.GetUtcNow());
132	        await unitOfWork.SalvarAsync(cancellationToken);
133	
134	        await emails.EnviarAsync(Mensagem(para, usuario, links.RedefinicaoDeSenha(token.Valor)), cancellationToken);
135	    }
136	
137	    // O mesmo texto serve ao esquecimento e ao primeiro acesso.
