1	using System.ComponentModel.DataAnnotations;
2	using System.Security.Claims;
3	using System.Security.Cryptography;
4	using System.Text.Json;
5	using Maxx.Api.Feed;
6	using Maxx.Api.Posts;
7	using Maxx.Api.Premios;
8	using Maxx.Application;
9	using Maxx.Application.Fotos;
10	using Maxx.Application.Paginacao;
11	using Maxx.Application.Perfil;
12	using Maxx.Application.Posts;
13	using Maxx.Application.Premios;
14	using Maxx.Application.Social;
15	using Maxx.Domain.Academico;
16	using Microsoft.AspNetCore.Http.HttpResults;
17	using Microsoft.Extensions.Options;
18	
19	namespace Maxx.Api.Perfil;
20	
21	// Perfil, grade de posts, prêmios, busca e editar perfil (produto.md 6.4 e 6.5).
22	internal static class PerfilEndpoints
23	{
24	    // Seis linhas da grade de três colunas.
25	    public const int PostsPorPagina = 18;
26	
27	    public const int AlunosPorPagina = 20;
28	
29	    public static IEndpointRouteBuilder MapPerfilEndpoints(this IEndpointRouteBuilder v1)
30	    {
31	        var perfis = v1.MapGroup("/perfis/{usuarioId:guid}").WithTags("Perfil");
32	
33	        perfis.MapGet("/", PerfilAsync)
34	            .WithName("GetPerfil")
35	            .Produces<PerfilResponse>()
36	            .Produces(StatusCodes.Status304NotModified)
37	            .ProducesProblem(StatusCodes.Status404NotFound);
38	
39	        perfis.MapGet("/posts", PostsAsync)
40	            .WithName("GetPostsDoPerfil")
41	            .ProducesProblem(StatusCodes.Status400BadRequest)
42	            .ProducesProblem(StatusCodes.Status404NotFound);
43	
44	        perfis.MapGet("/premios", PremiosAsync)
45	            .WithName("GetPremiosDoPerfil")
46	            .ProducesProblem(StatusCodes.Status404NotFound);
47	
48	        var eu = v1.MapGroup("/eu/perfil").WithTags("Perfil");
49	
50	        eu.MapGet("/", MeuPerfilAsync)
51	            .WithName("GetMeuPerfil")
52	            .Produces<PerfilResponse>()
53	            .Produces(StatusCodes.Status304NotModified);
54	
55	        eu.MapPatch("/", EditarAsync)
56	            .WithName("EditarPerfil")
57	            .Produces<PerfilResponse>()
58	            .ProducesValidationProblem()
59	            .ProducesProblem(StatusCodes.Status404NotFound)
60	            .ProducesProblem(StatusCodes.Status409Conflict);
61	
62	        eu.MapGet("/disponibilidade", DisponibilidadeAsync)
63	            .WithName("GetDisponibilidadeDoMeuPrefixo")
64	            .ProducesProblem(StatusCodes.Status400BadRequest);
65	
66	        v1.MapGet("/cursos", CursosAsync)
67	            .WithName("GetCursos")
68	            .WithTags("Busca");
69	
70	        v1.MapGet("/busca/alunos", BuscarAsync)
71	            .WithName("BuscarAlunos")
72	            .WithTags("Busca")
73	            .ProducesProblem(StatusCodes.Status400BadRequest);
74	
75	        return v1;
76	    }
77	
78	    private static async Task<IResult> PerfilAsync(
79	        Guid usuarioId,
80	        HttpContext http,
81	        ClaimsPrincipal principal,
82	        IConsultaDePerfil consulta,
83	        IArmazenamentoDeFotos armazenamento,
84	        CancellationToken cancellationToken)
85	    {
86	        var perfil = await consulta.PerfilAsync(usuarioId, PostEndpoints.UsuarioId(principal), cancellationToken)
87	            ?? throw NaoEncontrado(usuarioId);
88	        return ComEtag(http, PerfilResponse.De(perfil, armazenamento));
89	    }
90	
91	    private static Task<IResult> MeuPerfilAsync(
92	        HttpContext http,
93	        ClaimsPrincipal principal,
94	        IConsultaDePerfil consulta,
