8	namespace Maxx.Application.Medalhas;
9	
10	// Concessão de medalha pelo professor (fluxos/03-concessao-de-medalha.md): escopo de turma
11	// no banco, aluno com conta matriculado na turma, item do catálogo, limite por período e
12	// chave de deduplicação. A medalha, quem concedeu e quando, a notificação e os recálculos de
13	// ranking e raridade gravam juntos.
14	public sealed class ConcederMedalhaHandler(
15	    IEscopoDeTurma escopo,
16	    IUsuarioRepository usuarios,
17	    IMedalhaRepository medalhas,
18	    IFilaDeTrabalhos fila,
19	    IUnitOfWork unitOfWork,
20	    TimeProvider relogio)
21	{
22	    public async Task<Medalha> ConcederAsync(
23	        Guid professorId, Guid turmaId, Guid alunoId, string itemCodigo, CancellationToken cancellationToken)
24	    {
25	        ArgumentNullException.ThrowIfNull(itemCodigo);
26	
27	        try
28	        {
29	            return await TentarAsync(professorId, turmaId, alunoId, itemCodigo.Trim(), cancellationToken);
30	        }
31	        catch (ConflitoDeUnicidadeException conflito) when (conflito.Unicidade == Unicidade.MedalhaAtiva)
32	        {
33	            // Outra concessão do mesmo item ao mesmo aluno gravou a mesma vaga entre a
34	            // leitura e a gravação. Relida, a próxima vaga livre, se houver, é outra.
35	            unitOfWork.Descartar();
36	            try
37	            {
38	                return await TentarAsync(professorId, turmaId, alunoId, itemCodigo.Trim(), cancellationToken);
39	            }
40	            catch (ConflitoDeUnicidadeException falha) when (falha.Unicidade == Unicidade.MedalhaAtiva)
41	            {
42	                throw new RecusaException(
43	                    TipoDeRecusa.Conflito, CodigosDaMedalha.LimiteAtingido, $"Concessões simultâneas: {falha.Message}");
44	            }
45	        }
46	    }
47	
48	    private async Task<Medalha> TentarAsync(
49	        Guid professorId, Guid turmaId, Guid alunoId, string itemCodigo, CancellationToken cancellationToken)
50	    {
51	        if (!await escopo.ProfessorLecionaAsync(professorId, turmaId, cancellationToken))
52	        {
53	            throw new RecusaException(
54	                TipoDeRecusa.Proibido, CodigosDaMedalha.ForaDoEscopo, $"Professor {professorId} fora da turma {turmaId}.");
55	        }
56	
57	        var professor = await usuarios.BuscarAsync(professorId, cancellationToken)
58	            ?? throw new InvalidOperationException($"O professor {professorId} tem escopo e não existe.");
59	        var turma = await medalhas.TurmaAsync(turmaId, cancellationToken)
60	            ?? throw new InvalidOperationException($"A turma {turmaId} está no escopo e não existe.");
61	        var aluno = await medalhas.AlunoMatriculadoAsync(turmaId, alunoId, cancellationToken)
62	            ?? throw new RecusaException(
63	                TipoDeRecusa.NaoEncontrado, CodigosDaMedalha.AlunoForaDaTurma, $"Aluno {alunoId} sem conta ou fora da turma {turmaId}.");
64	        var item = await medalhas.ItemAsync(itemCodigo, cancellationToken)
65	            ?? throw new RecusaException(
66	                TipoDeRecusa.NaoEncontrado, CodigosDaMedalha.ItemNaoEncontrado, $"Medalha {itemCodigo} não está no catálogo.");
67	
68	        var resultado = Medalha.Conceder(
69	            item.Item,
70	            item.Versao,
71	            aluno.Aluno,
72	            aluno.SiglaDoCurso,
73	            turma.Turma,
74	            turma.Semestre,
75	            professor,
76	            await medalhas.DoAlunoNoItemAsync(alunoId, item.Item.Codigo, cancellationToken),
77	            relogio.GetUtcNow());
78	
