1	using System.Security.Cryptography;
2	using Maxx.Application.Autenticacao;
3	using Maxx.Application.Autenticacao.Termos;
4	using Maxx.Application.Fila;
5	using Maxx.Application.Medalhas;
6	using Maxx.Domain;
7	using Maxx.Domain.Academico;
8	using Maxx.Domain.Identidade;
9	
10	namespace Maxx.Application.Demonstracao;
11	
12	// O modo de demonstração da apresentação (produto.md 11). Só existe com a flag ligada; a
13	// borda nem mapeia as rotas sem ela.
14	public sealed class DemonstracaoHandler(
15	    IDemonstracaoRepository demonstracao,
16	    IUsuarioRepository usuarios,
17	    SugestaoDeArroba sugestoes,
18	    SessaoService sessoes,
19	    TermoDeUsoHandler termos,
20	    ITokenGenerator tokens,
21	    IFilaDeTrabalhos fila,
22	    IUnitOfWork unitOfWork,
23	    ConfiguracaoDaDemonstracao configuracao,
24	    TimeProvider relogio)
25	{
26	    // Um nome igual de outra pessoa da banca, registrado no mesmo instante, pode pegar o
27	    // mesmo prefixo: a gravação recusa, e o registro avança para a próxima sugestão livre.
28	    // Cada recusa de prefixo vem de outro pedido que gravou, então 10 tentativas cobrem até
29	    // 10 pedidos simultâneos com o mesmo nome.
30	    private const int _tentativas = 10;
31	
32	    private const string _alfabetoDoRa = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
33	
34	    // Os cursos em que dá para entrar agora: os que têm turma no semestre vigente.
35	    public Task<IReadOnlyList<Curso>> CursosAsync(CancellationToken cancellationToken) =>
36	        demonstracao.CursosComTurmaVigenteAsync(Hoje, cancellationToken);
37	
38	    public async Task<RegistroDeDemonstracao> RegistrarAsync(
39	        string nome, string siglaDoCurso, int versaoDoTermo, CancellationToken cancellationToken)
40	    {
41	        ArgumentNullException.ThrowIfNull(nome);
42	        ArgumentNullException.ThrowIfNull(siglaDoCurso);
43	
44	        try
45	        {
46	            nome = Usuario.ValidarNomeDeExibicao(nome);
47	        }
48	        catch (DomainException excecao)
49	        {
50	            throw new RecusaException(TipoDeRecusa.Invalido, CodigosDeRecusa.NomeDeExibicaoInvalido, excecao.Message);
51	        }
52	
53	        var termo = await termos.ConferirAceiteAsync(versaoDoTermo, cancellationToken);
54	        var (curso, turmas) = await demonstracao.TurmasVigentesAsync(siglaDoCurso.Trim(), Hoje, cancellationToken)
55	            ?? throw new RecusaException(
56	                TipoDeRecusa.NaoEncontrado, CodigosDeRecusa.CursoDeDemonstracaoIndisponivel, $"Sem turma vigente em {siglaDoCurso}.");
57	
58	        var recusados = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
59	        for (var tentativa = 1; ; tentativa++)
60	        {
61	            var prefixo = await sugestoes.PrimeiroLivreAsync(nome, recusados, cancellationToken);
62	            var chave = tokens.Generate();
63	            var cadastro = CadastroElegivel.AlunoDeDemonstracao(GerarRa(), nome, curso);
64	            var usuario = Usuario.EntrarNaDemonstracao(
65	                cadastro,
66	                curso,
67	                prefixo,
68	                chave.Hash,
69	                configuracao.Lote,
70	                relogio.GetUtcNow());
71	            usuario.AceitarTermo(termo, relogio.GetUtcNow());
72	
73	            demonstracao.Adicionar(cadastro);
74	            foreach (var turma in turmas)
75	            {
76	                demonstracao.Adicionar(new Matricula(cadastro, turma));
77	            }
78	
79	            usuarios.Adicionar(usuario);
80	
81	            // Aluno novo muda o divisor da raridade (ADR 0005). Na nova tentativa, o
82	            // Descartar leva o pedido junto, e ele é feito de novo aqui.
83	            fila.Enfileirar(new RecalcularRaridade());
84	            var sessao = sessoes.Abrir(usuario);
85	
86	            try
87	            {
88	                await unitOfWork.SalvarAsync(cancellationToken);
89	                return new RegistroDeDemonstracao(chave.Valor, sessao);
90	            }
91	            catch (ConflitoDeUnicidadeException) when (tentativa == _tentativas)
92	            {
93	                throw new RecusaException(
94	                    TipoDeRecusa.Conflito, CodigosDeRecusa.RegistroSimultaneo, $"Sem arroba livre depois de {_tentativas} tentativas.");
95	            }
96	            catch (ConflitoDeUnicidadeException conflito)
97	            {
98	                unitOfWork.Descartar();
99	                if (conflito.Unicidade == Unicidade.Prefixo)
100	                {
101	                    recusados.Add(prefixo);
102	                }
103	
104	                (curso, turmas) = (await demonstracao.TurmasVigentesAsync(curso.Sigla, Hoje, cancellationToken))!.Value;
105	            }
106	        }
107	    }
108	
