using System.Security.Cryptography;
using Maxx.Application.Autenticacao;
using Maxx.Application.Autenticacao.Termos;
using Maxx.Application.Fila;
using Maxx.Application.Medalhas;
using Maxx.Domain;
using Maxx.Domain.Academico;
using Maxx.Domain.Identidade;

namespace Maxx.Application.Demonstracao;

// O modo de demonstração da apresentação (produto.md 11). Só existe com a flag ligada; a
// borda nem mapeia as rotas sem ela.
public sealed class DemonstracaoHandler(
    IDemonstracaoRepository demonstracao,
    IUsuarioRepository usuarios,
    SugestaoDeArroba sugestoes,
    SessaoService sessoes,
    TermoDeUsoHandler termos,
    ITokenGenerator tokens,
    IFilaDeTrabalhos fila,
    IUnitOfWork unitOfWork,
    ConfiguracaoDaDemonstracao configuracao,
    TimeProvider relogio)
{
    // Um nome igual de outra pessoa da banca, registrado no mesmo instante, pode pegar o
    // mesmo prefixo: a gravação recusa, e o registro avança para a próxima sugestão livre.
    // Cada recusa de prefixo vem de outro pedido que gravou, então 10 tentativas cobrem até
    // 10 pedidos simultâneos com o mesmo nome.
    private const int _tentativas = 10;

    private const string _alfabetoDoRa = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";

    // Os cursos em que dá para entrar agora: os que têm turma no semestre vigente.
    public Task<IReadOnlyList<Curso>> CursosAsync(CancellationToken cancellationToken) =>
        demonstracao.CursosComTurmaVigenteAsync(Hoje, cancellationToken);

    public async Task<RegistroDeDemonstracao> RegistrarAsync(
        string nome, string siglaDoCurso, int versaoDoTermo, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(nome);
        ArgumentNullException.ThrowIfNull(siglaDoCurso);

        try
        {
            nome = Usuario.ValidarNomeDeExibicao(nome);
        }
        catch (DomainException excecao)
        {
            throw new RecusaException(TipoDeRecusa.Invalido, CodigosDeRecusa.NomeDeExibicaoInvalido, excecao.Message);
        }

        var termo = await termos.ConferirAceiteAsync(versaoDoTermo, cancellationToken);
        var (curso, turmas) = await demonstracao.TurmasVigentesAsync(siglaDoCurso.Trim(), Hoje, cancellationToken)
            ?? throw new RecusaException(
                TipoDeRecusa.NaoEncontrado, CodigosDeRecusa.CursoDeDemonstracaoIndisponivel, $"Sem turma vigente em {siglaDoCurso}.");

        var recusados = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        for (var tentativa = 1; ; tentativa++)
        {
            var prefixo = await sugestoes.PrimeiroLivreAsync(nome, recusados, cancellationToken);
            var chave = tokens.Generate();
            var cadastro = CadastroElegivel.AlunoDeDemonstracao(GerarRa(), nome, curso);
            var usuario = Usuario.EntrarNaDemonstracao(
                cadastro,
                curso,
                prefixo,
                chave.Hash,
                configuracao.Lote,
                relogio.GetUtcNow());
            usuario.AceitarTermo(termo, relogio.GetUtcNow());

            demonstracao.Adicionar(cadastro);
            foreach (var turma in turmas)
            {
                demonstracao.Adicionar(new Matricula(cadastro, turma));
            }

            usuarios.Adicionar(usuario);

            // Aluno novo muda o divisor da raridade (ADR 0005). Na nova tentativa, o
            // Descartar leva o pedido junto, e ele é feito de novo aqui.
            fila.Enfileirar(new RecalcularRaridade());
            var sessao = sessoes.Abrir(usuario);

            try
            {
                await unitOfWork.SalvarAsync(cancellationToken);
                return new RegistroDeDemonstracao(chave.Valor, sessao);
            }
            catch (ConflitoDeUnicidadeException) when (tentativa == _tentativas)
            {
                throw new RecusaException(
                    TipoDeRecusa.Conflito, CodigosDeRecusa.RegistroSimultaneo, $"Sem arroba livre depois de {_tentativas} tentativas.");
            }
            catch (ConflitoDeUnicidadeException conflito)
            {
                unitOfWork.Descartar();
                if (conflito.Unicidade == Unicidade.Prefixo)
                {
                    recusados.Add(prefixo);
                }

                (curso, turmas) = (await demonstracao.TurmasVigentesAsync(curso.Sigla, Hoje, cancellationToken))!.Value;
            }
        }
    }

    // Voltar pelo mesmo dispositivo abre uma sessão comum, com o refresh rotativo de todo
    // mundo.
    public async Task<Sessao> EntrarAsync(string chaveDoDispositivo, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(chaveDoDispositivo);

        var usuario = await demonstracao.BuscarPorChaveAsync(tokens.Hash(chaveDoDispositivo.Trim()), cancellationToken)
            ?? throw new RecusaException(
                TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.ChaveDoDispositivoInvalida, "Chave do dispositivo desconhecida.");

        var sessao = sessoes.Abrir(usuario);
        await unitOfWork.SalvarAsync(cancellationToken);
        return sessao;
    }

    private DateOnly Hoje => FusoHorario.DataLocal(relogio.GetUtcNow());

    // Fora do formato numérico dos RAs da faculdade, para nunca colidir com um real.
    private static string GerarRa() => $"DEMO{RandomNumberGenerator.GetString(_alfabetoDoRa, 8)}";
}

// O lote vale para todo aluno de demonstração criado enquanto ele estiver configurado: é a
// chave da purga depois da apresentação.
public sealed record ConfiguracaoDaDemonstracao(string Lote);

// A chave do dispositivo existe só aqui, a caminho do app: o banco guarda o hash.
public sealed record RegistroDeDemonstracao(string ChaveDoDispositivo, Sessao Sessao)
{
    public override string ToString() => "RegistroDeDemonstracao { }";
}

public interface IDemonstracaoRepository
{
    Task<IReadOnlyList<Curso>> CursosComTurmaVigenteAsync(DateOnly hoje, CancellationToken cancellationToken);

    // O curso pela sigla, com as turmas dele no semestre vigente. Nulo se não houver
    // nenhuma.
    Task<(Curso Curso, IReadOnlyList<Turma> Turmas)?> TurmasVigentesAsync(
        string sigla, DateOnly hoje, CancellationToken cancellationToken);

    Task<Usuario?> BuscarPorChaveAsync(string hashDaChave, CancellationToken cancellationToken);

    void Adicionar(CadastroElegivel cadastro);

    void Adicionar(Matricula matricula);
}

using System.ComponentModel.DataAnnotations;
using System.Security.Claims;
using Maxx.Api.Autenticacao;
using Maxx.Api.Medalhas;
using Maxx.Api.Posts;
using Maxx.Api.PremiosParticipacao;
using Maxx.Application.Fotos;
using Maxx.Application.Instituicao;
using Maxx.Application.Medalhas;
using Maxx.Application.PremiosParticipacao;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Instituicao;

// A área da instituição (produto.md 10.2, passo 12): busca e ficha do aluno, e os atos
// sobre a linha dele. Só a instituição; o papel é conferido de novo no banco.
internal static class InstituicaoEndpoints
{
    public static IEndpointRouteBuilder MapInstituicaoEndpoints(this IEndpointRouteBuilder v1)
    {
        var alunos = v1.MapGroup("/instituicao/alunos").WithTags("Instituicao").RequireAuthorization(Politicas.Instituicao);

        alunos.MapGet("/", BuscarAsync)
            .WithName("BuscarAlunosDaBase")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status403Forbidden);

        alunos.MapGet("/{cadastroId:guid}", FichaAsync)
            .WithName("GetFichaDoAluno")
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound);

        alunos.MapPut("/{cadastroId:guid}/email", CorrigirEmailAsync)
            .WithName("CorrigirEmailDoAluno")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        alunos.MapPost("/{cadastroId:guid}/ex-aluno", MarcarExAlunoAsync)
            .WithName("MarcarExAluno")
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        alunos.MapPut("/{cadastroId:guid}/curso", TrocarDeCursoAsync)
            .WithName("TrocarCursoDoAluno")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        // A concessão direta de prêmio de participação (passo 12, P2), com os eventos e as
        // matérias que ela oferece para o aluno.
        alunos.MapPost("/{cadastroId:guid}/premios-participacao", ConcederAsync)
            .WithName("ConcederPremioParticipacao")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        alunos.MapGet("/{cadastroId:guid}/eventos", EventosAsync)
            .WithName("GetEventosParaConcessao")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        alunos.MapGet("/{cadastroId:guid}/premios-participacao", ItensAsync)
            .WithName("GetPremiosParaConcessao")
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        alunos.MapGet("/{cadastroId:guid}/materias", MateriasAsync)
            .WithName("GetMateriasParaConcessao")
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        // A anulação pela área web: o mesmo ato do comando administrativo. Anular de novo não
        // muda nada e responde igual.
        v1.MapPost("/instituicao/medalhas/{medalhaId:guid}/anulacao", AnularAsync)
            .WithName("AnularMedalha")
            .WithTags("Instituicao")
            .RequireAuthorization(Politicas.Instituicao)
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound);

        // A purga da demonstração por lote (D14 do passo 7). Mapeada sempre, com a flag da
        // demonstração ligada ou não: a purga é depois da avaliação, com a flag já desligada.
        var lotes = v1.MapGroup("/instituicao/demonstracao/lotes").WithTags("Instituicao").RequireAuthorization(Politicas.Instituicao);

        lotes.MapGet("/", LotesAsync)
            .WithName("GetLotesDaDemonstracao")
            .ProducesProblem(StatusCodes.Status403Forbidden);

        lotes.MapPost("/{lote}/purga", PurgarAsync)
            .WithName("PurgarLoteDaDemonstracao")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound);

        return v1;
    }

    private static async Task<Ok<IReadOnlyList<LoteDaDemonstracaoResponse>>> LotesAsync(
        ClaimsPrincipal principal, PurgaDaDemonstracaoHandler handler, CancellationToken cancellationToken) =>
        TypedResults.Ok<IReadOnlyList<LoteDaDemonstracaoResponse>>([.. (await handler.LotesAsync(PostEndpoints.UsuarioId(principal), cancellationToken))
            .Select(lote => new LoteDaDemonstracaoResponse(lote.Lote, lote.Alunos, lote.PrimeiroEm, lote.UltimoEm, lote.Vigente))]);

    private static async Task<Ok<PurgaResponse>> PurgarAsync(
        [StringLength(64)] string lote,
        PurgaRequest pedido,
        ClaimsPrincipal principal,
        PurgaDaDemonstracaoHandler handler,
        CancellationToken cancellationToken)
    {
        var resultado = await handler.PurgarAsync(PostEndpoints.UsuarioId(principal), lote, pedido.Confirmacao, cancellationToken);
        return TypedResults.Ok(new PurgaResponse(resultado.Lote, resultado.Alunos, resultado.Fotos));

using System.ComponentModel.DataAnnotations;
using System.Security.Claims;
using Maxx.Api.Autenticacao;
using Maxx.Api.Medalhas;
using Maxx.Api.Posts;
using Maxx.Application.Fotos;
using Maxx.Application.PremiosParticipacao;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.PremiosParticipacao;

// A fila de comprovações e a decisão sobre cada uma (fluxos/02-post-com-comprovacao.md):
// professor e instituição. O papel do token só abre a porta; o escopo de turma do professor
// é conferido no banco a cada leitura e a cada decisão.
internal static class ComprovacaoEndpoints
{
    public static IEndpointRouteBuilder MapComprovacaoEndpoints(this IEndpointRouteBuilder v1)
    {
        var comprovacoes = v1.MapGroup("/comprovacoes").WithTags("Comprovacoes").RequireAuthorization(Politicas.Aprovador);

        comprovacoes.MapGet("/", PendentesAsync)
            .WithName("GetFilaDeComprovacoes")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status403Forbidden);

        comprovacoes.MapGet("/eventos", EventosAsync)
            .WithName("GetEventosDaFilaDeComprovacoes")
            .ProducesProblem(StatusCodes.Status403Forbidden);

        comprovacoes.MapPost("/{comprovacaoId:guid}/aprovacao", AprovarAsync)
            .WithName("AprovarComprovacao")
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        comprovacoes.MapPost("/{comprovacaoId:guid}/reprovacao", ReprovarAsync)
            .WithName("ReprovarComprovacao")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        return v1;
    }

    // As pendentes, das mais antigas para as mais novas, 20 por página; com o evento, só as dele.
    private static async Task<Ok<PaginaDeComprovacoesResponse>> PendentesAsync(
        ClaimsPrincipal principal,
        FilaDeComprovacoesHandler handler,
        IArmazenamentoDeFotos armazenamento,
        CancellationToken cancellationToken,
        Guid? eventoId = null,
        string? cursor = null)
    {
        var pagina = await handler.PendentesAsync(PostEndpoints.UsuarioId(principal), eventoId, cursor, cancellationToken);
        return TypedResults.Ok(new PaginaDeComprovacoesResponse(
            [.. pagina.Itens.Select(comprovacao => ComprovacaoNaFilaResponse.De(comprovacao, armazenamento))], pagina.Proximo));
    }

    private static async Task<Ok<IReadOnlyList<EventoNaFilaResponse>>> EventosAsync(
        ClaimsPrincipal principal, FilaDeComprovacoesHandler handler, CancellationToken cancellationToken) =>
        TypedResults.Ok<IReadOnlyList<EventoNaFilaResponse>>([.. (await handler.EventosAsync(PostEndpoints.UsuarioId(principal), cancellationToken))
            .Select(evento => new EventoNaFilaResponse(evento.Id, evento.Nome, evento.Inicio, evento.Pendentes))]);

    private static async Task<NoContent> AprovarAsync(
        Guid comprovacaoId, ClaimsPrincipal principal, DecidirComprovacaoHandler handler, CancellationToken cancellationToken)
    {
        await handler.AprovarAsync(PostEndpoints.UsuarioId(principal), comprovacaoId, cancellationToken);
        return TypedResults.NoContent();
    }

    private static async Task<NoContent> ReprovarAsync(
        Guid comprovacaoId,
        ReprovacaoRequest pedido,
        ClaimsPrincipal principal,
        DecidirComprovacaoHandler handler,
        CancellationToken cancellationToken)
    {
        await handler.ReprovarAsync(PostEndpoints.UsuarioId(principal), comprovacaoId, pedido.Motivo, cancellationToken);
        return TypedResults.NoContent();
    }
}

// O limite do motivo (500 caracteres, contando emoji como um) é do domínio; aqui, só um teto
// bruto para o corpo.
public sealed record ReprovacaoRequest([property: StringLength(4000)] string? Motivo);

public sealed record PaginaDeComprovacoesResponse(IReadOnlyList<ComprovacaoNaFilaResponse> Itens, string? Proximo);

// Uma comprovação pendente: o aluno, o item com tier e pontos do momento, o evento, a foto e a
// legenda do post. PassouDoPrazo: a marca de 7 dias. Materias: as do aluno no semestre
// vigente; para o professor, só as que ele também leciona.
public sealed record ComprovacaoNaFilaResponse(
    Guid Id,
    Guid PremioId,
    Guid? PostId,
    AutorDoPostResponse Aluno,
    string Item,
    string NomeDoItem,
    string Tier,
    int Pontos,
    EventoDaComprovacaoResponse Evento,
    string? Materia,
    FotoDoPostResponse? Foto,
    string? Legenda,
    DateTimeOffset ReivindicadaEm,
    bool PassouDoPrazo,
    IReadOnlyList<string> Materias)
{
    public static ComprovacaoNaFilaResponse De(ComprovacaoNaFila comprovacao, IArmazenamentoDeFotos armazenamento) => new(
        comprovacao.Id,
        comprovacao.PremioId,
        comprovacao.PostId,
        new AutorDoPostResponse(
            comprovacao.Aluno.Id,
            comprovacao.Aluno.NomeDeExibicao,
            comprovacao.Aluno.Arroba,
            comprovacao.Aluno.Curso,
            comprovacao.Aluno.Semestre,
            PostResponse.Leitura(armazenamento, comprovacao.Aluno.ChaveDaFoto)),
        comprovacao.Item,
        comprovacao.NomeDoItem,
        ProfessorEndpoints.Nome(comprovacao.Tier),
        comprovacao.Pontos,
        new EventoDaComprovacaoResponse(
            comprovacao.Evento.Id, comprovacao.Evento.Nome, comprovacao.Evento.Inicio, comprovacao.Evento.Fim, comprovacao.Evento.Digitado),
        comprovacao.Materia,
        comprovacao is { ChaveDaFotoDoFeed: { } feed, ChaveDaFotoDaGrade: { } grade }
            ? new FotoDoPostResponse(armazenamento.UrlDeLeitura(feed).AbsoluteUri, armazenamento.UrlDeLeitura(grade).AbsoluteUri)
            : null,
        comprovacao.Legenda,
        comprovacao.ReivindicadaEm,
        comprovacao.PassouDoPrazo,
        comprovacao.Materias);
}

// Digitado: o evento é texto livre do aluno, não do seed.
public sealed record EventoDaComprovacaoResponse(Guid Id, string Nome, DateOnly Inicio, DateOnly Fim, bool Digitado);

public sealed record EventoNaFilaResponse(Guid Id, string Nome, DateOnly Inicio, int Pendentes);

