14	namespace Maxx.Application.PremiosParticipacao;
15	
16	// Aprovação e reprovação da comprovação (fluxos/02-post-com-comprovacao.md). Decide o
17	// professor de uma turma do aluno no semestre vigente, conferido no banco, ou a instituição;
18	// vale quem chega primeiro, e o xmin do prêmio fecha a corrida. A decisão, quem decidiu e
19	// quando, e os trabalhos da fila gravam juntos.
20	public sealed class DecidirComprovacaoHandler(
21	    IUsuarioRepository usuarios,
22	    IEscopoDeTurma escopo,
23	    IPremioParticipacaoRepository premios,
24	    IPostRepository posts,
25	    IFilaDeTrabalhos fila,
26	    IUnitOfWork unitOfWork,
27	    TimeProvider relogio)
28	{
29	    // Aprovado, o prêmio pontua na hora: os recálculos de ranking e raridade e a notificação
30	    // vão para a fila, e o fim da janela de contestação fica agendado.
31	    public async Task AprovarAsync(Guid quemId, Guid comprovacaoId, CancellationToken cancellationToken)
32	    {
33	        var (quem, premio, aluno) = await CarregarAsync(quemId, comprovacaoId, cancellationToken);
34	
35	        if (premio.Aprovar(aluno, quem, relogio.GetUtcNow()) is { } recusa)
36	        {
37	            throw Recusa(recusa, comprovacaoId);
38	        }
39	
40	        fila.Enfileirar(new NotificarComprovacaoAprovada(premio.Id));
41	        fila.PedirRecalculos();
42	        fila.Enfileirar(new TornarPremioDefinitivo(premio.Id), premio.FimDaJanela);
43	        await SalvarAsync(comprovacaoId, cancellationToken);
44	    }
45	
46	    // Reprovado, a reivindicação se encerra: o post perde o vínculo e fica como post comum.
47	    // Reivindicado não pontuava, então nada muda no ranking nem na raridade.
48	    public async Task ReprovarAsync(Guid quemId, Guid comprovacaoId, string? motivo, CancellationToken cancellationToken)
49	    {
50	        var (quem, premio, _) = await CarregarAsync(quemId, comprovacaoId, cancellationToken);
51	
52	        if (premio.Reprovar(quem, motivo, relogio.GetUtcNow()) is { } recusa)
53	        {
54	            throw Recusa(recusa, comprovacaoId);
55	        }
56	
57	        foreach (var post in await posts.DoPremioParticipacaoAsync(premio.Id, cancellationToken))
58	        {
59	            // O post de reivindicação sempre tem foto: desvincular nunca o deixa vazio.
60	            post.DesvincularPremio();
61	        }
62	
63	        fila.Enfileirar(new NotificarComprovacaoReprovada(premio.Id));
64	        await SalvarAsync(comprovacaoId, cancellationToken);
65	    }
66	
67	    private async Task<(Usuario Quem, PremioParticipacao Premio, Usuario Aluno)> CarregarAsync(
68	        Guid quemId, Guid comprovacaoId, CancellationToken cancellationToken)
69	    {
70	        var quem = await usuarios.BuscarAsync(quemId, cancellationToken)
71	            ?? throw new RecusaException(TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.SessaoInvalida, $"Usuário {quemId} não existe.");
72	        var comprovacao = await premios.ComprovacaoAsync(comprovacaoId, cancellationToken)
73	            ?? throw new RecusaException(
74	                TipoDeRecusa.NaoEncontrado, CodigosDoPremioParticipacao.ComprovacaoNaoEncontrada, $"Comprovação {comprovacaoId} não existe.");
75	        var premio = await premios.BuscarAsync(comprovacao.PremioParticipacaoId, cancellationToken)
76	            ?? throw new InvalidOperationException($"A comprovação {comprovacaoId} não tem prêmio.");
77	
78	        // A instituição decide qualquer comprovação; o professor, só a de aluno seu no
79	        // semestre vigente, conferido no banco (ADR 0006), nunca lido do token.
80	        if (!quem.Papeis.HasFlag(Papeis.Instituicao)
81	            && !await escopo.ProfessorEnsinaAlunoAsync(quemId, premio.AlunoId, cancellationToken))
82	        {
