85	        }
86	
87	        var aluno = await usuarios.BuscarAsync(premio.AlunoId, cancellationToken)
88	            ?? throw new InvalidOperationException($"O prêmio {premio.Id} não tem aluno.");
89	        return (quem, premio, aluno);
90	    }
