1	using System.ComponentModel.DataAnnotations;
2	using System.Security.Claims;
3	using Maxx.Api.Medalhas;
4	using Maxx.Api.Posts;
5	using Maxx.Application;
6	using Maxx.Application.Fotos;
7	using Maxx.Application.Mural;
8	using Maxx.Application.Perfil;
9	using Maxx.Application.Social;
10	using Maxx.Domain.Mural;
11	using Microsoft.AspNetCore.Http.HttpResults;
12	
13	namespace Maxx.Api.Mural;
14	
15	// O aviso do mural (produto.md 7). Publicar é do professor (turmas suas) e da instituição
16	// (faculdade e cursos); quem decide o papel é o domínio, e o escopo de turma, o banco. Ler
17	// é de qualquer usuário logado, pelo mural dele: os vínculos do banco decidem o que ele vê.
18	internal static class AvisoEndpoints
19	{
20	    public const int AvisosPorPagina = 20;
21	
22	    public static IEndpointRouteBuilder MapAvisoEndpoints(this IEndpointRouteBuilder v1)
23	    {
24	        var avisos = v1.MapGroup("/avisos").WithTags("Mural");
25	
26	        avisos.MapPost("/", PublicarAsync)
27	            .WithName("PublicarAviso")
28	            .ProducesValidationProblem()
29	            .ProducesProblem(StatusCodes.Status403Forbidden)
30	            .ProducesProblem(StatusCodes.Status404NotFound)
31	            .ProducesProblem(StatusCodes.Status409Conflict);
32	
33	        avisos.MapGet("/{avisoId:guid}", AvisoAsync)
34	            .WithName("GetAviso")
35	            .Produces<AvisoResponse>()
36	            .Produces(StatusCodes.Status304NotModified)
37	            .ProducesProblem(StatusCodes.Status404NotFound);
38	
39	        avisos.MapPut("/{avisoId:guid}/leitura", LerAsync)
40	            .WithName("LerAviso")
41	            .ProducesProblem(StatusCodes.Status404NotFound);
42	
43	        var mural = v1.MapGroup("/mural").WithTags("Mural");
44	
45	        mural.MapGet("/", MuralAsync)
46	            .WithName("GetMural")
47	            .Produces<PaginaDoMuralResponse>()
48	            .Produces(StatusCodes.Status304NotModified)
49	            .ProducesValidationProblem();
50	
51	        mural.MapPost("/leitura", LerTodosAsync)
52	            .WithName("LerTodosOsAvisos");
53	
54	        // Os avisos que o professor publicou, no perfil dele (produto.md 2.1): pela mesma
55	        // regra do mural, cada um vê só os que estão no mural dele.
56	        v1.MapGet("/perfis/{usuarioId:guid}/avisos", DoAutorAsync)
57	            .WithName("GetAvisosDoPerfil")
58	            .WithTags("Perfil")
59	            .ProducesProblem(StatusCodes.Status400BadRequest)
60	            .ProducesProblem(StatusCodes.Status404NotFound);
61	
62	        return v1;
63	    }
64	
65	    // O mural combinado, filtrado pelos vínculos de quem pede, com ETag: o app pergunta de
66	    // novo ao voltar à aba, e a resposta não muda na maior parte das vezes.
67	    private static async Task<IResult> MuralAsync(
68	        [AllowedValues(null, PublicarAvisoRequest.Faculdade, PublicarAvisoRequest.Curso, PublicarAvisoRequest.Turma)] string? escopo,
69	        string? cursor,
70	        HttpContext http,
71	        ClaimsPrincipal principal,
72	        MuralHandler handler,
73	        IArmazenamentoDeFotos armazenamento,
74	        CancellationToken cancellationToken)
75	    {
76	        var pagina = await handler.MuralAsync(
77	            PostEndpoints.UsuarioId(principal), Escopo(escopo), null, cursor, AvisosPorPagina, cancellationToken);
78	        return Perfil.PerfilEndpoints.ComEtag(http, PaginaDoMuralResponse.De(pagina, armazenamento));
79	    }
80	
81	    private static async Task<Ok<PaginaDoMuralResponse>> DoAutorAsync(
82	        Guid usuarioId,
83	        string? cursor,
84	        ClaimsPrincipal principal,
85	        MuralHandler handler,
86	        IConsultaDePerfil perfis,
87	        IArmazenamentoDeFotos armazenamento,
88	        CancellationToken cancellationToken)
89	    {
90	        // Perfil inexistente é 404, como na grade de posts do perfil.
91	        var leitor = PostEndpoints.UsuarioId(principal);
92	        _ = await perfis.PerfilAsync(usuarioId, leitor, cancellationToken)
93	            ?? throw new RecusaException(
94	                TipoDeRecusa.NaoEncontrado, CodigosSociais.UsuarioNaoEncontrado, $"Usuário {usuarioId} sem perfil.");
95	        var pagina = await handler.MuralAsync(leitor, null, usuarioId, cursor, AvisosPorPagina, cancellationToken);
96	        return TypedResults.Ok(PaginaDoMuralResponse.De(pagina, armazenamento));
97	    }
98	
99	    private static async Task<IResult> AvisoAsync(
100	        Guid avisoId,
101	        HttpContext http,
102	        ClaimsPrincipal principal,
103	        MuralHandler handler,
104	        IArmazenamentoDeFotos armazenamento,
105	        CancellationToken cancellationToken)
106	    {
107	        var aviso = await handler.AvisoAsync(PostEndpoints.UsuarioId(principal), avisoId, cancellationToken);
108	        return Perfil.PerfilEndpoints.ComEtag(http, AvisoResponse.De(aviso, armazenamento));
109	    }
110	
111	    private static async Task<NoContent> LerAsync(
112	        Guid avisoId, ClaimsPrincipal principal, MuralHandler handler, CancellationToken cancellationToken)
113	    {
114	        await handler.LerAsync(PostEndpoints.UsuarioId(principal), avisoId, cancellationToken);
115	        return TypedResults.NoContent();
116	    }
117	
118	    private static async Task<NoContent> LerTodosAsync(
119	        ClaimsPrincipal principal, MuralHandler handler, CancellationToken cancellationToken)
120	    {
121	        await handler.LerTodosAsync(PostEndpoints.UsuarioId(principal), cancellationToken);
122	        return TypedResults.NoContent();
123	    }
124	
125	    private static EscopoDoAviso? Escopo(string? escopo) => escopo switch
126	    {
127	        PublicarAvisoRequest.Faculdade => EscopoDoAviso.Faculdade,
128	        PublicarAvisoRequest.Curso => EscopoDoAviso.Curso,
129	        PublicarAvisoRequest.Turma => EscopoDoAviso.Turma,
130	        _ => null,
131	    };
132	
133	    private static async Task<Created<AvisoPublicadoResponse>> PublicarAsync(
134	        PublicarAvisoRequest pedido,
135	        ClaimsPrincipal principal,
136	        PublicarAvisoHandler handler,
