1	using Maxx.Application.Autenticacao;
2	using Maxx.Application.Autorizacao;
3	using Maxx.Application.Fila;
4	using Maxx.Application.Fotos;
5	using Maxx.Domain.Fotos;
6	using Maxx.Domain.Mural;
7	
8	namespace Maxx.Application.Mural;
9	
10	public interface IAvisoRepository
11	{
12	    void Adicionar(Aviso aviso);
13	
14	    // Quantos dos cursos pedidos existem: o aviso de curso não aponta para curso inexistente.
15	    Task<int> CursosExistentesAsync(IReadOnlyCollection<Guid> cursoIds, CancellationToken cancellationToken);
16	}
17	
18	// Publicação de aviso (produto.md 7). O papel, a forma e os alvos são do domínio; aqui, o
19	// escopo de turma do professor no banco, a existência dos cursos, a foto no bucket e a
20	// gravação. Na mesma transação, o trabalho que grava a notificação de aviso novo de cada
21	// destinatário (D4 do passo 10): sem aviso gravado, nenhuma notificação; com aviso, todas.
22	public sealed class PublicarAvisoHandler(
23	    IUsuarioRepository usuarios,
24	    IUploadPendenteRepository uploads,
25	    IAvisoRepository avisos,
26	    IEscopoDeTurma escopo,
27	    IArmazenamentoDeFotos armazenamento,
28	    IFilaDeTrabalhos fila,
29	    IUnitOfWork unitOfWork,
30	    TimeProvider relogio)
31	{
32	    public async Task<Aviso> PublicarAsync(
33	        Guid autorId,
34	        EscopoDoAviso escopoDoAviso,
35	        IReadOnlyCollection<Guid> alvos,
36	        string? titulo,
37	        string? texto,
38	        Guid? uploadId,
39	        CancellationToken cancellationToken)
40	    {
41	        ArgumentNullException.ThrowIfNull(alvos);
42	
43	        var autor = await usuarios.BuscarAsync(autorId, cancellationToken)
44	            ?? throw new RecusaException(TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.SessaoInvalida, $"Usuário {autorId} não existe.");
45	
46	        // O papel antes do escopo: o aluno que pede turma ouve que não publica, não que a
47	        // turma não é dele.
48	        if (!Aviso.PodePublicar(autor, escopoDoAviso))
49	        {
50	            throw Recusa(RecusaDoAviso.AutorNaoPublica, autorId);
51	        }
52	
53	        // O escopo de turma do professor é do banco, nunca do token (CLAUDE.md, Segurança):
54	        // uma turma de fora recusa o aviso inteiro.
55	        if (escopoDoAviso == EscopoDoAviso.Turma)
56	        {
57	            foreach (var turmaId in alvos.Distinct())
58	            {
59	                if (!await escopo.ProfessorLecionaAsync(autorId, turmaId, cancellationToken))
60	                {
61	                    throw new RecusaException(
62	                        TipoDeRecusa.Proibido, CodigosDoMural.ForaDoEscopo, $"Professor {autorId} fora da turma {turmaId}.");
63	                }
64	            }
65	        }
66	
67	        if (escopoDoAviso == EscopoDoAviso.Curso)
68	        {
69	            var distintos = alvos.Distinct().ToList();
70	            if (await avisos.CursosExistentesAsync(distintos, cancellationToken) != distintos.Count)
71	            {
72	                throw new RecusaException(TipoDeRecusa.NaoEncontrado, CodigosDoMural.CursoNaoEncontrado, "Curso inexistente no aviso.");
73	            }
74	        }
75	
76	        UploadPendente? upload = null;
77	        if (uploadId is { } idDoUpload)
78	        {
79	            upload = await uploads.BuscarAsync(idDoUpload, cancellationToken)
80	                ?? throw Recusa(RecusaDoAviso.UploadNaoEncontrado, autorId);
81	        }
82	
83	        var resultado = Aviso.Publicar(autor, escopoDoAviso, alvos, titulo, texto, upload, relogio.GetUtcNow());
84	        if (resultado.Aviso is not { } aviso)
85	        {
86	            throw Recusa(resultado.Recusa!.Value, autorId);
87	        }
88	
89	        // O app diz que enviou; o bucket confirma, como no post.
90	        if (upload is not null)
91	        {
92	            foreach (var chave in upload.Chaves)
93	            {
94	                if (!await armazenamento.ExisteAsync(chave, cancellationToken))
95	                {
96	                    throw new RecusaException(TipoDeRecusa.Conflito, CodigosDoMural.FotoNaoEnviada, $"Objeto {chave} não chegou ao bucket.");
97	                }
98	            }
99	        }
100	
101	        avisos.Adicionar(aviso);
102	        fila.Enfileirar(new NotificarAvisoNovo(aviso.Id));
103	        try
104	        {
105	            await unitOfWork.SalvarAsync(cancellationToken);
106	        }
107	        catch (ConflitoDeConcorrenciaException)
108	        {
109	            // Outro aviso ou post confirmou o mesmo upload entre a leitura e a gravação.
110	            throw new RecusaException(TipoDeRecusa.Conflito, CodigosDoMural.UploadJaUsado, $"Upload {uploadId} usado ao mesmo tempo.");
111	        }
112	
113	        return aviso;
114	    }
115	
116	    private static RecusaException Recusa(RecusaDoAviso recusa, Guid autorId) => recusa switch
117	    {
118	        RecusaDoAviso.AutorNaoPublica => new(
119	            TipoDeRecusa.Proibido, CodigosDoMural.AvisoNaoPermitido, $"{autorId} não publica aviso nesse escopo."),
120	        RecusaDoAviso.AlvosInvalidos => new(TipoDeRecusa.Invalido, CodigosDoMural.AlvosDoAvisoInvalidos, "Alvos fora do escopo."),
121	        RecusaDoAviso.TituloInvalido => new(TipoDeRecusa.Invalido, CodigosDoMural.TituloDoAvisoInvalido, "Título fora do tamanho."),
122	        RecusaDoAviso.TextoInvalido => new(TipoDeRecusa.Invalido, CodigosDoMural.TextoDoAvisoInvalido, "Texto fora do tamanho."),
123	        RecusaDoAviso.UploadNaoEncontrado => new(
124	            TipoDeRecusa.NaoEncontrado, CodigosDoMural.UploadNaoEncontrado, $"Upload inexistente ou alheio para {autorId}."),
125	        RecusaDoAviso.UploadJaUsado => new(TipoDeRecusa.Conflito, CodigosDoMural.UploadJaUsado, "Upload já confirmado."),
126	        _ => throw new ArgumentOutOfRangeException(nameof(recusa), recusa, null),
127	    };
128	}
129	
130	// Grava a notificação de aviso novo de cada destinatário (produto.md 7 e 8).
131	public sealed record NotificarAvisoNovo(Guid AvisoId) : ICargaDeTrabalho
132	{
133	    public static string Tipo => "notificar-aviso-novo";
134	}
135	
136	// A distribuição em lote, de uma vez no banco, para um aviso de faculdade não passar dos
137	// 60 s do trabalho (D4 do passo 10).
138	public interface IDistribuicaoDeAviso
139	{
140	    // Grava uma notificação de aviso novo para cada destinatário que ainda não a tem e
141	    // devolve quantas gravou. Os destinatários são fixados no instante da publicação:
142	    // quem ganhou conta, virou ex-aluno ou trocou de vínculo depois não muda o conjunto.
143	    //
144	    // - Aluno ativo naquele instante, alcançado pelo escopo: todos na faculdade, o curso
145	    //   atual no curso, a matrícula na turma.
146	    // - Professor, só no aviso de faculdade.
147	    // - Nunca o autor. Ex-aluno lê o mural, mas não é notificado.
